// ─────────────────────────────────────────────────────────────────────────
//  04 · fail loudly, with the id                                     ★★☆
//  concepts: Optional.orElseThrow(Supplier) · NoSuchElementException · lazily built messages
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    record Order(String id) {}

    /** The order if present; otherwise throw NoSuchElementException("order " + id). */
    static Order require(Optional<Order> o, String id) {
        throw new UnsupportedOperationException("TODO: orElseThrow can build your own exception");
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a present order is returned", () ->
            eq(require(Optional.of(new Order("42")), "42"), new Order("42")));
        test("an empty order throws NoSuchElementException naming the id (boundary)", () ->
            raises(NoSuchElementException.class, () -> require(Optional.empty(), "42"), "order 42"));
        test("the message is exactly order and the id", () -> {
            var ex = raises(NoSuchElementException.class, () -> require(Optional.empty(), "7"));
            eq(ex.getMessage(), "order 7");
        });
        test("the present path ignores the id argument", () ->
            eq(require(Optional.of(new Order("42")), "unused"), new Order("42")));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

