// ─────────────────────────────────────────────────────────────────────────
//  08 · optional inside Optional                                     ★★☆
//  concepts: Optional.flatMap identity · nested Optionals · lazy N-source search
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;

class Exercise {

    /** Collapse one level of nesting: present-of-present → present, anything else → empty. */
    static Optional<String> flatten(Optional<Optional<String>> oo) {
        return oo.flatMap(o -> o);
    }

    /** Ask each source in order, counting every ask; stop at the first present answer. */
    static Optional<String> firstPresentOf(List<Supplier<Optional<String>>> sources, AtomicInteger asked) {
        for (Supplier<Optional<String>> source : sources) {
            asked.incrementAndGet();
            Optional<String> answer = source.get();
            if (answer.isPresent()) return answer;
        }
        return Optional.empty();
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("present inside present flattens to the value", () ->
            eq(flatten(Optional.of(Optional.of("x"))), Optional.of("x")));
        test("present wrapping empty flattens to empty", () ->
            eq(flatten(Optional.of(Optional.empty())), Optional.empty()));
        test("an empty outer stays empty (boundary)", () ->
            eq(flatten(Optional.empty()), Optional.empty()));
        test("firstPresentOf stops at the second of three sources", () -> {
            var calls = new ArrayList<String>();
            var asked = new AtomicInteger();
            List<Supplier<Optional<String>>> sources = List.of(
                () -> { calls.add("s1"); return Optional.empty(); },
                () -> { calls.add("s2"); return Optional.of("b"); },
                () -> { calls.add("s3"); return Optional.of("c"); });
            eq(firstPresentOf(sources, asked), Optional.of("b"));
            eq(asked.get(), 2);
            eq(calls, List.of("s1", "s2"));
        });
        test("firstPresentOf with no answer asks everyone and is empty", () -> {
            var asked = new AtomicInteger();
            List<Supplier<Optional<String>>> sources = List.of(() -> Optional.empty(), () -> Optional.empty());
            eq(firstPresentOf(sources, asked), Optional.empty());
            eq(asked.get(), 2);
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}
